import { Field, MerkleTree, Provable } from 'o1js';
import { syntheticRecords } from '../src/fixtures.js';
import { BatchQuery, membershipBatchProgram, requestedIdsHash } from '../src/membership-batch.js';
import { encodeRecord, encodedRecordCommitment, EncodedRecord } from '../src/records.js';
import { RECORD_TREE_HEIGHT, RecordWitness } from '../src/registry.js';
import { batchIndices, batchSweepProtocol } from '../src/experiments/batch-sweep.js';

// Constraint evaluation only; no proof is generated by these tests.
describe('batch membership constraints', () => {
  const k = 3;
  const { program, Records, Salts, Witnesses } = membershipBatchProgram(k);
  const records = syntheticRecords(6, 20261014);
  const encoded = records.map(encodeRecord);
  const salts = records.map((_, i) => Field(201 + i));
  const tree = new MerkleTree(RECORD_TREE_HEIGHT);
  encoded.slice(0, 5).forEach((e, i) => tree.setLeaf(BigInt(i), encodedRecordCommitment(e, salts[i]))); // record 5 unregistered
  const witness = (i: number) => new RecordWitness(tree.getWitness(BigInt(i)));
  const idsHash = (idx: number[]) => requestedIdsHash(idx.map((i) => encoded[i].recordIdHash));
  async function check(query: BatchQuery, idx: number[], recs = idx.map((i) => encoded[i]), sls = idx.map((i) => salts[i]), wits = idx.map(witness)) {
    await Provable.runAndCheck(async () => {
      await program.rawMethods.proveBatch(
        Provable.witness(BatchQuery, () => query),
        Provable.witness(Records, () => recs),
        Provable.witness(Salts, () => sls),
        Provable.witness(Witnesses, () => wits)
      );
    });
  }
  const valid = [0, 2, 4];

  test('accepts registered records matching the requested ordered list', async () => {
    await expect(check(new BatchQuery({ root: tree.getRoot(), requestedIdsHash: idsHash(valid) }), valid)).resolves.toBeUndefined();
  });
  test('rejects a batch member that is not under the root', async () => {
    const idx = [0, 2, 5];
    await expect(check(new BatchQuery({ root: tree.getRoot(), requestedIdsHash: idsHash(idx) }), idx, undefined, undefined, [witness(0), witness(2), witness(4)])).rejects.toThrow();
  });
  test('rejects a reordered requested list', async () => {
    await expect(check(new BatchQuery({ root: tree.getRoot(), requestedIdsHash: idsHash([2, 0, 4]) }), valid)).rejects.toThrow();
  });
  test('rejects a substituted record and a wrong root', async () => {
    const swapped: EncodedRecord[] = [encoded[0], encoded[1], encoded[4]];
    await expect(check(new BatchQuery({ root: tree.getRoot(), requestedIdsHash: idsHash(valid) }), valid, swapped)).rejects.toThrow();
    await expect(check(new BatchQuery({ root: Field(9), requestedIdsHash: idsHash(valid) }), valid)).rejects.toThrow();
  });
  test('rows grow linearly with batch size', async () => {
    const r1 = (await membershipBatchProgram(1).program.analyzeMethods()).proveBatch.rows;
    const r4 = (await membershipBatchProgram(4).program.analyzeMethods()).proveBatch.rows;
    expect(r4).toBeGreaterThan(3 * r1);
    expect(r4).toBeLessThan(5 * r1);
  });
  test('rejects batch sizes outside the supported range', () => {
    expect(() => membershipBatchProgram(0)).toThrow(/batch size/);
    expect(() => membershipBatchProgram(257)).toThrow(/batch size/);
  });
  test('protocol and indices are deterministic, distinct and in range', () => {
    const p = batchSweepProtocol(false);
    expect(p).toMatchObject({ protocol: 'batch-sweep-v1', reportable: true, records: 1000, proofMeasured: 10, verifications: 3 });
    for (const size of p.batchSizes) {
      const idx = batchIndices(size, p.records);
      expect(new Set(idx).size).toBe(size);
      expect(Math.max(...idx)).toBeLessThan(p.records);
    }
    expect(batchSweepProtocol(true).reportable).toBe(false);
  });
});
